function sizeLabel(size: number) { if (!size) return '—'; if(size < 1024) return `${size} B`; if(size < 1048576) return `${(size / 1024).toFixed(1)} KB`; if(size < 1073741824) return `${(size / 1048576).toFixed(1)} MB`; return `${(size / 1073741824).toFixed(2)} GB` }
const splitTags = (value: string) => [...new Set(value.split(/[,，;；\n]/).map(s => s.trim()).filter(Boolean))];
const kindLabel = (kind: AssetRecord['kind']) => ({ folder: t("素材文件夹"), archive: t("压缩包"), unitypackage: t("Unity 素材包"), file: t("文件"), 'unity-project': t("Unity 工程") }[kind]);
function assetIntroduction(asset:AssetRecord):string {
  const text=(asset.online.description??'').replace(/https?:\/\/\S+/g,'').replace(/<[^>]+>/g,' ').split(/(?:利用規約|使用条款|版权声明|Terms of Use|License)/i)[0].trim();
  if(text){const characters=Array.from(text.replace(/\s+/g,' '));return characters.slice(0,300).join('')+(characters.length>300?'…':'')}
  return t("本地{v0}，尚未获取商品介绍。可查看本地文件或添加商品来源了解用途。", {v0: kindLabel(asset.kind)});
}
