function EnrichmentActions({api,run,selected,enabled}:{api:LibraryAPI;run:Runner;selected:string[];enabled:boolean}) {
  useLanguage();
  const [menu,setMenu]=useState<{x:number;y:number;top:number}|null>(null),menuRef=useRef<HTMLDivElement>(null),toggleRef=useRef<HTMLButtonElement>(null);
  const close=useCallback(()=>setMenu(null),[]);
  const open=()=>{const rect=toggleRef.current?.getBoundingClientRect();if(rect)setMenu({x:rect.right-223,y:rect.bottom+7,top:rect.top})};
  useEffect(()=>{if(!enabled)close()},[enabled,close]);
  useLayoutEffect(()=>{if(!menu)return;const rect=menuRef.current?.getBoundingClientRect();if(rect){const x=Math.max(8,Math.min(menu.x,window.innerWidth-rect.width-8));const preferred=menu.y+rect.height>window.innerHeight-8?menu.top-rect.height-7:menu.y;const y=Math.max(8,Math.min(preferred,window.innerHeight-rect.height-8));if(x!==menu.x||y!==menu.y)setMenu({...menu,x,y})}menuRef.current?.querySelector<HTMLButtonElement>('button')?.focus()},[menu]);
  useEffect(()=>{if(!menu)return;const outside=(event:PointerEvent)=>{if(!menuRef.current?.contains(event.target as Node)&&!toggleRef.current?.contains(event.target as Node))close()};const key=(event:KeyboardEvent)=>{if(event.key==='Escape'){event.preventDefault();close();toggleRef.current?.focus()}else if(event.key==='ArrowDown'||event.key==='ArrowUp'||event.key==='Home'||event.key==='End'){event.preventDefault();const buttons=[...(menuRef.current?.querySelectorAll<HTMLButtonElement>('button:not(:disabled)')??[])];const index=buttons.indexOf(document.activeElement as HTMLButtonElement);const next=event.key==='Home'?0:event.key==='End'?buttons.length-1:(index+(event.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length;buttons[next]?.focus()}else if(event.key==='Tab')close()};window.addEventListener('pointerdown',outside,true);window.addEventListener('keydown',key);window.addEventListener('resize',close);window.addEventListener('blur',close);window.addEventListener('wheel',close,{passive:true});return()=>{window.removeEventListener('pointerdown',outside,true);window.removeEventListener('keydown',key);window.removeEventListener('resize',close);window.removeEventListener('blur',close);window.removeEventListener('wheel',close)}},[menu,close]);
  return <div className="enrichment-split"><button className="button small primary enrichment-primary" disabled={!enabled} title={selected.length?t("重新查找所选素材，包含之前未匹配的条目"):t("补全新发现、等待处理的素材")} onClick={()=>{close();run(()=>selected.length?api.enrich(selected,true):api.enrich(),selected.length?t("所选素材已加入重新匹配队列"):t("素材已加入补全队列"))}}><Icon name="spark"/>{t("在线补全")}</button><button ref={toggleRef} className="button small primary enrichment-toggle" aria-label={t("在线补全选项")} aria-haspopup="menu" aria-expanded={!!menu} disabled={!enabled} onClick={()=>menu?close():open()} onKeyDown={event=>{if(event.key==='ArrowDown'&&!menu&&enabled){event.preventDefault();open()}}}><Icon name="chevron" size={13}/></button>{menu&&createPortal(<div ref={menuRef} className="context-menu enrichment-menu" role="menu" aria-label={t("在线补全选项")} style={{left:menu.x,top:menu.y}}><div className="context-title">{t("查找尚未匹配的素材")}</div><button role="menuitem" onClick={()=>{close();run(()=>api.enrich(undefined,true),t("未匹配素材已加入重新匹配队列"))}}><Icon name="refresh" size={15}/>{t("重试未匹配")}</button><p>{t("重新检查待确认、未找到及失败条目，保留已匹配商品。")}</p></div>,document.body)}</div>;
}

