      {materialAddErrors.length>0&&<details className="manual-add-errors"><summary>{t("有 {count} 项未添加，请查看读取提示",{count:materialAddErrors.length})}</summary><ul>{materialAddErrors.map((error,index)=><li key={index}>{error}</li>)}</ul><button className="text-button" onClick={()=>setMaterialAddErrors([])}>{t("关闭提示")}</button></details>}
