type Runner = (action:()=>Promise<unknown>,message?:string)=>Promise<boolean>;
type AnnotationDraft={title:string;category:string;tags:string;avatars:string;notes:string;projectStatus:string};
const annotationDrafts=new Map<string,{draft:AnnotationDraft;fields:Set<keyof AnnotationDraft>}>();
function Detail({menuPreferences,onRecycle,onRematch,asset,onStep,index,itemCount,onlineEnabled,api,run,onClose,onDialog,onContext,origin,onOpenMaterial,onReturnProject,onProjectTools}:{menuPreferences?:ContextMenuPreferences;onRecycle:(ids:string[],scope?:'card'|'file')=>Promise<void>;onRematch:(ids:string[])=>Promise<void>;asset:AssetRecord;onStep:(delta:number)=>void;index:number;itemCount:number;onlineEnabled:boolean;api:LibraryAPI;run:Runner;onClose:()=>void;onDialog:(d:Dialog)=>void;onContext:(e:React.MouseEvent)=>void;origin?:AssetRecord;onOpenMaterial:(asset:AssetRecord)=>void;onReturnProject:()=>void;onProjectTools:(request:ProjectToolRequest)=>void}) {
  useLanguage();
  const [tab,setTab]=useState<'info'|'files'>('info'); const [listing,setListing]=useState<FileListing>();const [fileError,setFileError]=useState('');const [fileLoading,setFileLoading]=useState(false);
  const [draft,setDraft]=useState({title:'',category:'未分类',tags:'',avatars:'',notes:'',projectStatus:''});const [dirty,setDirty]=useState(false);const [saving,setSaving]=useState(false);const editingAsset=useRef(asset.id);const editedFields=useRef(new Set<keyof typeof draft>());
  useLayoutEffect(()=>{if(dirty&&editingAsset.current===asset.id)return;editingAsset.current=asset.id;const cached=annotationDrafts.get(asset.id);if(cached){editedFields.current=new Set(cached.fields);setDraft({...cached.draft});setDirty(true)}else{editedFields.current.clear();setDraft({title:displayTitle(asset),category:displayCategory(asset),tags:displayTags(asset).join('，'),avatars:(asset.manual.avatars??[]).join('，'),notes:asset.manual.notes??'',projectStatus:asset.manual.projectStatus??''});setDirty(false)}},[asset.id,asset.updatedAt]);
  useEffect(()=>{setListing(undefined);setFileError('');setTab('info')},[asset.id]);
  useEffect(()=>{if(tab!=='files'||listing)return;let active=true;setFileLoading(true);api.files(asset.id).then(data=>{if(active){setListing(data);setFileLoading(false)}}).catch(e=>{if(active){setFileError(String(e));setFileLoading(false)}});return()=>{active=false}},[tab,asset.id,listing,api]);
  const edit=(key:keyof typeof draft,value:string)=>{editedFields.current.add(key);const next={...draft,[key]:value};annotationDrafts.set(asset.id,{draft:next,fields:new Set(editedFields.current)});setDraft(next);setDirty(true)};
  const save=async()=>{setSaving(true);const patch:ManualInfo={};for(const key of editedFields.current){if(key==='title')patch.title=draft.title.trim();else if(key==='category')patch.category=draft.category as ManualInfo['category'];else if(key==='tags'||key==='avatars')patch[key]=splitTags(draft[key]);else if(key==='notes')patch.notes=draft.notes;else if(key==='projectStatus'&&draft.projectStatus)patch.projectStatus=draft.projectStatus as ManualInfo['projectStatus'];}if(await run(()=>api.annotate([asset.id],patch),t("标注已保存"))){annotationDrafts.delete(asset.id);if(editingAsset.current===asset.id){editedFields.current.clear();setDirty(false)}}setSaving(false)};
  return <aside className="detail-panel" onContextMenu={onContext}><div className="detail-header"><strong>{t("素材详情")}</strong><div><button className="icon-button detail-previous" aria-label={t("上一项素材")} disabled={index<=0} onClick={()=>onStep(-1)}>‹</button><button className="icon-button" aria-label={t("下一项素材")} disabled={index<0||index>=itemCount-1} onClick={()=>onStep(1)}>›</button><button className="icon-button" title={t("打开所在文件夹")} onClick={()=>run(()=>api.reveal(asset.id))}><Icon name="folder" size={17}/></button><button className="icon-button" aria-label={t("收起详情")} onClick={onClose}><Icon name="close" size={18}/></button></div></div><div className="detail-scroll">{origin&&<button className="text-button project-return" aria-label={t("返回工程：{v0}", {v0: origin.name})} onClick={onReturnProject}>{t("‹ 返回工程：")}{displayTitle(origin)}</button>}<div className="detail-cover"><Cover asset={asset} large/><button className="cover-change" onClick={()=>run(()=>api.setCover(asset.id))}><Icon name="image" size={15}/>{asset.kind==='unity-project'?t("添加截图"):t("更换封面")}</button></div><div className="detail-title"><h2>{displayTitle(asset)}</h2><button className={`icon-button ${asset.manual.favorite?'is-favorite':''}`} title={asset.manual.favorite?t("取消收藏"):t("收藏")} onClick={()=>run(()=>api.annotate([asset.id],{favorite:!asset.manual.favorite}))}><Icon name="heart" size={20}/></button></div><p className="detail-subtitle">{asset.online.author||t("本地素材")}<span>·</span>{kindLabel(asset.kind)}</p><div className="detail-tabs"><button className={tab==='info'?'active':''} onClick={()=>setTab('info')}>{t("信息与标注")}</button><button className={tab==='files'?'active':''} onClick={()=>setTab('files')}>{t("文件列表")}</button></div>
    {tab==='files'?<div className="file-list"><div className="section-label">{t("只读浏览")}<span>{listing?.entries.length??0} {" "}{t("项")}</span></div>{fileLoading&&<p className="help-text">{t("正在读取文件列表…")}</p>}{fileError&&<p className="help-text error-text">{t(fileError)}</p>}{listing?.message&&<p className="file-notice">{t(listing.message)}</p>}{listing?.entries.map((f,i)=><div className="file-entry" key={`${f.name}-${i}`}><Icon name={f.directory?'folder':'box'} size={15}/><span title={f.name}>{f.name}</span><small>{f.directory?'':sizeLabel(f.size)}</small></div>)}{listing?.truncated&&<p className="help-text">{t("列表已截断；可打开文件夹查看完整内容。")}</p>}{listing&&!listing.entries.length&&!listing.message&&<p className="help-text">{t("没有可显示的文件。")}</p>}</div>:<>
      <div className="detail-section"><div className="section-label">{t("本地信息")}</div><div className="metadata-row"><span>{t("分组")}</span><strong>{asset.group||t("未分组")}</strong></div><div className="metadata-row"><span>{t("文件大小")}</span><strong>{asset.kind === 'folder' || asset.kind === 'unity-project' ? t("目录（未统计总大小）") : sizeLabel(asset.size)}</strong></div><div className="path-box"><span title={asset.path}>{asset.path}</span><div><button className="text-button" onClick={()=>run(()=>api.reveal(asset.id))}><Icon name="folder" size={14}/>{t("打开路径")}</button><button className="text-button" onClick={()=>run(()=>api.copyPath(asset.id),t("路径已复制"))}><Icon name="copy" size={14}/>{t("复制")}</button></div></div>{asset.missing&&<p className="file-notice danger">{t("原文件暂时无法找到；你的标注仍然保留。")}</p>}<div className="rematch-tools">{asset.kind!=='unity-project'&&<button className="button small" data-force-rematch onClick={()=>onRematch([asset.id])}>{t("强制重新匹配")}</button>}<button className="button small" data-hide-material onClick={()=>run(()=>api.setHidden([asset.id],true),t("已从资料库隐藏，可在“已隐藏素材”中恢复"))}>{t("从资料库隐藏")}</button></div><Members asset={asset} api={api} run={run} preferences={menuPreferences} onSettings={()=>onDialog({type:'settings',section:'context-menu'})} onRecycle={onRecycle}/></div>
      <div className="detail-section"><div className="section-label">{t("商品来源")}<span className={`status-label status-${asset.online.status}`}>{t(STATUS[asset.online.status])}</span></div>{asset.online.url?<button className="source-link" onClick={()=>run(()=>api.openSource(asset.id))}><Icon name="link" size={16}/><span>{asset.online.author?`${asset.online.author} · `:''}{t("打开商品页面")}</span><Icon name="arrow" size={15}/></button>:<p className="help-text">{t("添加来源后，可以自动补充封面和标签。")}</p>}{asset.online.message&&<p className="help-text">{t(asset.online.message)}</p>}{asset.storage?.cloudCount?<section className="detail-section cloud-local-locations"><h3>{t('存放位置')}</h3><StorageBadge storage={asset.storage}/><p className="help-text">{t('云端记录仅代表曾读取到商品或文件线索，不保证版本及内容相同。')}</p>{asset.storage.cloudEntries.map(entry=><p className="project-path" key={entry.key}>{entry.path}</p>)}</section>:null}<ProductFacts product={asset.online}/>{asset.online.candidates?.length? <div className="candidate-list"><p>{t("确认哪一个商品对应此素材")}</p><CandidateCoverLoader asset={asset} api={api} run={run} enabled={onlineEnabled}/>{asset.online.candidates.map(c=><div className="candidate" key={c.url}><div className="detail-candidate-cover"><CandidateCover candidate={c}/></div><strong>{c.title}</strong><span>{c.author||(c.reason?t(c.reason):c.url)}</span><div className="candidate-actions"><button className="button small" disabled={!onlineEnabled} onClick={()=>run(()=>api.previewSource(asset.id,c.url))}><Icon name="search" size={12}/>{t("预览网页")}</button><button className="button small" disabled={!onlineEnabled} onClick={()=>run(()=>api.acceptCandidate(asset.id,c.url),t("商品来源已确认"))}>{t("使用此商品")}</button><button className="text-button reject-candidate" onClick={()=>run(()=>api.rejectCandidate(asset.id,c.url),t("已排除此商品"))}>{t("排除此商品")}</button></div></div>)}</div>:null}<div className="source-actions">{asset.manual.matchingMode==='manual'?<button className="text-button" onClick={()=>run(()=>api.restoreMatching(asset.id),t("已恢复自动匹配"))}>{t("恢复自动匹配")}</button>:asset.kind!=='unity-project'&&<button className="text-button" onClick={()=>run(()=>api.skipMatching(asset.id),t("已移入手动归类"))}>{t("移至手动归类")}</button>}{!!asset.online.rejectedUrls?.length&&<button className="text-button" onClick={()=>run(()=>api.restoreRejectedCandidates(asset.id),t("已恢复排除记录，可重新匹配"))}>{t("恢复已排除 ·")}{" "}{asset.online.rejectedUrls.length}</button>}{asset.online.url&&<button className="text-button" disabled={!onlineEnabled} onClick={()=>run(()=>api.previewSource(asset.id,asset.online.url!))}><Icon name="search" size={14}/>{t("预览商品")}</button>}<button className="text-button" onClick={()=>onDialog({type:'link',id:asset.id})}><Icon name="link" size={14}/>{asset.online.url?t("修改来源"):t("粘贴商品链接")}</button><button className="text-button" onClick={()=>run(()=>api.enrich([asset.id],true),t("已加入补全队列"))}><Icon name="spark" size={14}/>{t("重新匹配")}</button></div></div>
      {asset.kind==='unity-project'&&<ProjectMaterials asset={asset} api={api} onOpen={onOpenMaterial} onManage={()=>onDialog({type:'relations',asset})} onBrowse={()=>onProjectTools({type:'files',project:asset})} onProducts={()=>onProjectTools({type:'products',project:asset})} onImport={()=>onProjectTools({type:'import',project:asset})}/>}<AssetEvidence asset={asset}/>{asset.kind!=='unity-project'&&<Compatibility asset={asset}/>}
      <div className="detail-section annotation-section"><div className="section-label">{t("我的标注")}{dirty&&<span className="unsaved">{t("未保存")}</span>}</div><label className="field">{t("显示名称")}<input value={draft.title} onChange={e=>edit('title',e.target.value)}/></label><div className="field-pair"><label className="field">{t("分类")}<select aria-label={t("素材分类")} value={draft.category} onChange={e=>edit('category',e.target.value)}>{CATEGORIES.map(c=><option key={c} value={c}>{t(c)}</option>)}</select></label>{asset.kind==='unity-project'&&<label className="field">{t("工程状态")}<select aria-label={t("工程状态")} value={draft.projectStatus} onChange={e=>edit('projectStatus',e.target.value)}><option value="">{t("未标记")}</option><option value="制作中">{t("制作中")}</option><option value="已完成">{t("已完成")}</option></select></label>}</div><label className="field">{t("自定义标签")}<input placeholder={t("用逗号分隔，如：日常，夏日")} value={draft.tags} onChange={e=>edit('tags',e.target.value)}/></label><label className="field">{t("我确认的适配模型")}<input placeholder={t("手动确认本地包含的模型，用逗号分隔")} value={draft.avatars} onChange={e=>edit('avatars',e.target.value)}/></label><label className="field">{t("备注")}<textarea aria-label={t("备注")} rows={3} placeholder={t("记录使用方式、搭配想法…")} value={draft.notes} onChange={e=>edit('notes',e.target.value)}/></label><button className="button primary save-button" disabled={!dirty||saving} onClick={save}><Icon name="check" size={16}/>{saving?t("正在保存…"):t("保存标注")}</button></div>
      {asset.kind!=='unity-project'&&<div className="detail-section"><button className="button primary detail-import-button" disabled={asset.missing} onClick={()=>onProjectTools({type:'import',source:asset})}>{t('导入到工程')}</button></div>}
      <div className="detail-section related-section"><div className="section-label">{t("关联素材")}<span>{asset.manual.relatedIds?.length??0} {" "}{t("项")}</span></div><p className="help-text">{t("将素材包、解压目录和使用它们的工程联系起来。")}</p><button className="button" onClick={()=>onDialog({type:'relations',asset})}><Icon name="link" size={15}/>{t("管理关联")}</button></div>
    </>}</div></aside>;
}

function ContextMenu({onRematch,onRecycle,preferences,context,onClose,api,run,onDialog,onOpen,onProjectTools}:{onRematch:(ids:string[])=>Promise<void>;onRecycle:(ids:string[])=>Promise<void>;preferences?:ContextMenuPreferences;context:Context;onClose:()=>void;api:LibraryAPI;run:Runner;onDialog:(d:Dialog)=>void;onOpen:(a:AssetRecord)=>void;onProjectTools:(request:ProjectToolRequest)=>void}) {
  useLanguage();
  const ref=useRef<HTMLDivElement>(null),[position,setPosition]=useState({x:context.x,y:context.y}),{asset,ids}=context;
  const prefs=normalizeContextMenuPreferences(preferences);
  useLayoutEffect(()=>{const r=ref.current?.getBoundingClientRect();if(r)setPosition({x:Math.max(8,Math.min(context.x,window.innerWidth-r.width-8)),y:Math.max(8,Math.min(context.y,window.innerHeight-r.height-8))});ref.current?.querySelector<HTMLButtonElement>('button:not(:disabled)')?.focus()},[context]);
  useEffect(()=>{const outside=(e:PointerEvent)=>{if(!ref.current?.contains(e.target as Node))onClose()};const key=(e:KeyboardEvent)=>{if(e.key==='Escape'){e.preventDefault();onClose()}else if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const buttons=[...(ref.current?.querySelectorAll<HTMLButtonElement>('button:not(:disabled)')??[])],index=buttons.indexOf(document.activeElement as HTMLButtonElement);buttons[(index+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus()}else if(e.key==='Tab')onClose()};window.addEventListener('pointerdown',outside,true);window.addEventListener('keydown',key);window.addEventListener('resize',onClose);window.addEventListener('blur',onClose);return()=>{window.removeEventListener('pointerdown',outside,true);window.removeEventListener('keydown',key);window.removeEventListener('resize',onClose);window.removeEventListener('blur',onClose)}},[onClose]);
  const project=asset.kind==='unity-project';
  const actions:Record<ContextActionId,{label:string;icon:IconName;visible?:boolean;disabled?:boolean;run:()=>unknown}>={
    details:{label:t('查看详情'),icon:'box',run:()=>onOpen(asset)},
    reveal:{label:t('打开所在文件夹'),icon:'folder',run:()=>run(()=>api.reveal(asset.id))},
    'copy-path':{label:t('复制路径'),icon:'copy',run:()=>run(()=>api.copyPath(asset.id),t('路径已复制'))},
    'open-source':{label:t('打开商品页面'),icon:'link',disabled:!asset.online.url,run:()=>run(()=>api.openSource(asset.id))},
    'project-products':{label:t('读取工程内商品'),icon:'box',visible:project,run:()=>onProjectTools({type:'products',project:asset})},
    'project-files':{label:t('查看工程文件'),icon:'folder',visible:project,run:()=>onProjectTools({type:'files',project:asset})},
    'import-project':{label:project?t('导入本地素材'):t('导入到工程'),icon:'download',run:()=>onProjectTools(project?{type:'import',project:asset}:{type:'import',source:asset})},
    favorite:{label:asset.manual.favorite?t('取消收藏'):t('添加收藏'),icon:'heart',run:()=>run(()=>api.annotate(ids,{favorite:!asset.manual.favorite}),asset.manual.favorite?t('已取消收藏'):t('已添加收藏'))},
    tags:{label:ids.length>1?t('批量添加标签'):t('添加标签'),icon:'tag',run:()=>onDialog({type:'bulk',ids})},
    category:{label:t('修改分类'),icon:'grid',run:()=>onDialog({type:'bulk',ids,category:true})},
    relations:{label:t('关联素材'),icon:'link',run:()=>onDialog({type:'relations',asset})},
    'project-in-progress':{label:t('标记为制作中'),icon:'folder',visible:project,run:()=>run(()=>api.annotate([asset.id],{projectStatus:'制作中'}),t('工程状态已更新'))},
    'project-completed':{label:t('标记为已完成'),icon:'check',visible:project,run:()=>run(()=>api.annotate([asset.id],{projectStatus:'已完成'}),t('工程状态已更新'))},
    'matching-mode':{label:asset.manual.matchingMode==='manual'?t('恢复自动匹配'):t('移至手动归类'),icon:'spark',visible:!project,run:()=>run(()=>asset.manual.matchingMode==='manual'?api.restoreMatching(asset.id):api.skipMatching(asset.id),asset.manual.matchingMode==='manual'?t('已恢复自动匹配'):t('已移入手动归类'))},
    collection:{label:t('加入集合'),icon:'folder',run:()=>onDialog({type:'collection-members',ids})},
    'remove-tags':{label:t('移除标签'),icon:'tag',run:()=>onDialog({type:'remove-tags',ids})},
    cover:{label:project?t('添加工程截图'):t('更换封面'),icon:'image',run:()=>run(()=>api.setCover(asset.id))},
    'force-rematch':{label:t('强制重新匹配'),icon:'spark',visible:!project,run:()=>onRematch(ids)},
    hide:{label:ids.length>1?t('批量隐藏'):t('从资料库隐藏'),icon:'close',run:()=>run(()=>api.setHidden(ids,true),t('已从资料库隐藏，可在“已隐藏素材”中恢复'))},
    delete:{label:ids.length>1?t('批量删除（移入回收站）'):t('删除（移入回收站）'),icon:'close',visible:!project,run:()=>onRecycle(ids)}
  };
  return <div ref={ref} className="context-menu" role="menu" style={{left:position.x,top:position.y}} onContextMenu={e=>e.preventDefault()}><div className="context-title">{ids.length>1?t('已选择 {v0} 个条目',{v0:ids.length}):displayTitle(asset)}</div>{prefs.order.filter(id=>!prefs.hidden.includes(id)&&actions[id].visible!==false).map(id=>{const item=actions[id];return <button key={id} role="menuitem" data-context-id={id} className={id==='delete'?'recycle-danger':id==='hide'?'hide-material':undefined} disabled={item.disabled} onClick={()=>{onClose();void item.run()}}><Icon name={item.icon} size={16}/>{item.label}</button>})}<div className="context-divider"/><button role="menuitem" data-context-id="settings" onClick={()=>{onClose();onDialog({type:'settings',section:'context-menu'})}}><Icon name="settings" size={16}/>{t('设置右键菜单')}</button></div>;
}

function Modal({suspended=false,dialog,snapshot,api,run,onClose,tell,busy,setBusy,onShowUpdates,onShowHidden}:{suspended?:boolean;dialog:BasicDialog;snapshot?:Snapshot;api:LibraryAPI;run:Runner;onClose:()=>void;tell:(message:string,error?:boolean)=>void;busy:boolean;setBusy:(b:boolean)=>void;onShowUpdates:()=>void;onShowHidden:()=>void}) {
  useLanguage();
  const [value,setValue]=useState('');const [category,setCategory]=useState('未分类');const [results,setResults]=useState<AssetRecord[]>([]);const [related,setRelated]=useState<Set<string>>(new Set(dialog.type==='relations'?dialog.asset.manual.relatedIds??[]:[]));const [relationLoading,setRelationLoading]=useState(false);const modalRef=useRef<HTMLDivElement>(null);
  useEffect(()=>{if(suspended)return;const handler=(e:KeyboardEvent)=>{if(e.key==='Escape'&&!busy)onClose();if(e.key==='Tab'){const els=[...(modalRef.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled)')??[])];const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}};window.addEventListener('keydown',handler);modalRef.current?.querySelector<HTMLElement>('input,button')?.focus({preventScroll:true});return()=>window.removeEventListener('keydown',handler)},[onClose,busy,suspended]);
  useEffect(()=>{if(dialog.type==='settings'&&dialog.section){const section=dialog.section;requestAnimationFrame(()=>modalRef.current?.querySelector<HTMLElement>(`[data-setting="${section}"]`)?.scrollIntoView({block:'start'}))}},[dialog]);
  useEffect(()=>{if(dialog.type!=='relations')return;let active=true;setRelationLoading(true);const timer=setTimeout(()=>api.list({view:'all',search:value,limit:80,sort:'name'}).then(page=>{if(active){setResults(page.items.filter(a=>a.id!==dialog.asset.id));setRelationLoading(false)}}).catch(e=>{if(active){setRelationLoading(false);tell(String(e),true)}}),180);return()=>{active=false;clearTimeout(timer)}},[dialog,value,api,tell]);
  const save=async()=>{setBusy(true);let ok=false;if(dialog.type==='bulk'){if(dialog.category)ok=await run(()=>api.annotate(dialog.ids,{category:category as ManualInfo['category']}),t("分类已更新"));else {const additions=splitTags(value);ok=await run(()=>api.updateTags(dialog.ids,additions,[]),t("标签已添加"))}}else if(dialog.type==='link')ok=await run(()=>api.linkSource(dialog.id,value.trim()),t("来源已保存并加入补全队列"));else if(dialog.type==='relations')ok=await run(()=>api.annotate([dialog.asset.id],{relatedIds:[...related]}),t("关联已保存"));setBusy(false);if(ok)onClose()};
  const name=dialog.type==='settings'?t("设置与备份"):dialog.type==='bulk'?dialog.category?t("修改素材分类"):t("添加素材标签"):dialog.type==='link'?t("添加商品来源"):t("关联素材");
  return <div className="modal-overlay" inert={suspended} aria-hidden={suspended||undefined} onMouseDown={e=>{if(e.target===e.currentTarget&&!busy)onClose()}}><div ref={modalRef} className={`modal ${dialog.type==='relations'?'relation-modal':''}`} role="dialog" aria-modal="true" aria-label={name}><div className="modal-header"><div className="modal-symbol"><Icon name={dialog.type==='settings'?'settings':dialog.type==='bulk'?'tag':'link'} size={21}/></div><h2>{name}</h2><button className="icon-button" aria-label={t("关闭弹窗")} disabled={busy} onClick={onClose}><Icon name="close"/></button></div><div className="modal-body">
    {dialog.type==='settings'?<><LanguageSettings onChange={language=>run(()=>api.setViewPreferences({language}))}/><UpdateSettings api={api} run={run} onShowHistory={onShowUpdates} navigationDisabled={busy}/><ThemeSettings value={snapshot?.settings.theme??initialTheme} onChange={theme=>run(()=>api.setViewPreferences({theme}))}/>{!!snapshot?.warnings?.length&&<div className="setting-block recovery-details"><h3>{t("资料库读取提示")}</h3><p>{t("原记录保留，可以检查资料库位置、重新读取或从备份恢复。")}</p><ul>{snapshot.warnings.map((warning,index)=><li key={index}>{t(warning)}</li>)}</ul></div>}<ContextMenuSettings value={normalizeContextMenuPreferences(snapshot?.settings.contextMenu)} onChange={value=>api.setContextMenuPreferences(value)} disabled={busy}/><div className="setting-block hidden-settings-shortcut" data-setting="hidden"><h3>{t("已隐藏素材")} · {snapshot?.stats.hidden??0}</h3><p>{t("已隐藏的条目集中在左侧“已隐藏素材”页面管理。")}</p><button className="button" data-open-hidden disabled={busy} onClick={onShowHidden}>{t("查看已隐藏素材")}</button></div><div className="setting-block"><h3>{t("素材位置")}</h3><p>{t("扫描此位置。原素材和工程保持原样。")}</p>{snapshot?.settings.roots.map(root=><div className="setting-path" key={root}><Icon name="folder" size={16}/><span>{root}</span>{snapshot.settings.directSources?.includes(root)&&<small className="setting-direct-source">{t("手动添加")}</small>}<button className="button small root-remove" data-remove-root={root} aria-label={t("移除素材路径：{path}", {path:root})} disabled={busy||snapshot?.scan.running} onClick={async()=>{setBusy(true);try{await run(()=>api.removeRoot(root))}finally{setBusy(false)}}}>{t("移除")}</button></div>)}<p className="help-text">{t("手动添加只读取所选内容；移除路径保留原文件和标注。")}</p><p className="help-text">{t("此文件夹及其子文件夹都会递归扫描。")}</p><p className="help-text">{t("仅停止扫描此路径，保留原文件和标注。")}</p><button className="button" onClick={async()=>{setBusy(true);await run(()=>api.chooseRoot());setBusy(false)}} disabled={busy}>{t("添加素材文件夹")}</button></div><div className="setting-block"><h3>{t("资料库数据")}</h3><p>{t("标签、封面与设置保存在独立位置。")}</p><div className="setting-path selectable">{snapshot?.settings.dataDir||t("正在读取…")}</div><p className="help-text">{t("可选中文字并复制此路径。")}</p><button className="button data-migrate" disabled={busy} onClick={async()=>{setBusy(true);await run(()=>api.chooseDataDir());setBusy(false)}}><Icon name="folder" size={16}/>{t("更改保存位置")}</button><p className="help-text">{t("选择 C 盘以外的位置，完成后应用会重新启动。原资料库会保留。")}</p></div><div className="setting-block"><h3>{t("显示大小")}</h3><p>{t("按住 Ctrl 并滚动鼠标滚轮调整整个界面的大小。")}</p><div className="zoom-actions"><select aria-label={t("界面缩放")} value={snapshot?.settings.uiZoom??1} onChange={e=>run(()=>api.setZoom(Number(e.target.value)))}>{[...new Set([snapshot?.settings.uiZoom??1,.67,.8,1,1.25,1.5,2])].sort((a,b)=>a-b).map(value=><option value={value} key={value}>{Math.round(value*100)}%</option>)}</select><button className="button" onClick={()=>run(()=>api.setZoom(1))}>{t("重置为 100%")}</button></div></div><div className="setting-block"><h3>{t("网络与代理")}</h3><label className="setting-online"><input type="checkbox" aria-label={t("启用在线补全")} checked={snapshot?.settings.onlineEnabled??false} onChange={e=>run(()=>api.setOnlineEnabled(e.target.checked))}/>{t("启用在线补全")}</label><p>{t("使用系统代理设置；连接状态通过实际网页请求检查。")}</p><ProxyState proxy={snapshot?.proxy} api={api} run={run}/><ConcurrencySelect value={snapshot?.settings.downloadConcurrency??3} api={api} run={run} label={t("下载并发任务数")}/><p className="help-text">{t("默认同时处理 3 个素材，可选择 1～6 个。BOOTH 网页保留请求间隔，封面图片可并发下载。")}</p></div><div className="setting-block" data-setting="xianyu"><h3>{t("辅助搜索")}</h3><label className="setting-online"><input type="checkbox" aria-label={t("启用闲鱼搜索")} checked={snapshot?.settings.xianyuEnabled??false} disabled={busy||!snapshot} onChange={async event=>{const value=event.currentTarget.checked;setBusy(true);try{await run(()=>api.setXianyuEnabled(value))}finally{setBusy(false)}}}/>{t("启用闲鱼搜索")}</label><p>{t("默认关闭；开启后在匹配确认显示“进行闲鱼尝试补全”。")}</p><p className="help-text">{t("仅用于辅助搜索，不可用于购买。")}</p></div><div className="setting-block"><h3>{t("备份与恢复")}</h3><p>{t("备份整理信息和封面；不包含原素材。备份位置由你选择。")}</p><div className="setting-path selectable backup-path">{snapshot?.settings.backupDir||t("未选择，导出备份前选择位置")}</div><button className="button choose-backup" disabled={busy} onClick={async()=>{setBusy(true);await run(()=>api.chooseBackupDir());setBusy(false)}}><Icon name="folder" size={16}/>{t("选择备份位置")}</button><p className="help-text">{t("请选择 C 盘之外、素材目录之外的文件夹。")}</p><div className="setting-actions"><button className="button" disabled={busy} onClick={async()=>{setBusy(true);try{const path=await api.backup();if(path)tell(t("备份已保存：{v0}", {v0: path}))}catch(e){tell(String(e),true)}setBusy(false)}}><Icon name="download" size={16}/>{t("导出备份")}</button><button className="button" disabled={busy} onClick={async()=>{setBusy(true);await run(async()=>{if(await api.restore())tell(t("资料库已恢复"))});setBusy(false)}}><Icon name="refresh" size={16}/>{t("恢复备份（合并）")}</button></div></div><div className="settings-notice"><Icon name="cloud" size={19}/><div>{t("联网只使用商品检索线索")}<p>{t("不会上传素材包或 Unity 工程。自动匹配有歧义时，交给你确认。")}</p></div></div></>:
      dialog.type==='bulk'?<><p className="modal-description">{t("将更新 {count} 个条目的{field}，原文件保持原样。",{count:dialog.ids.length,field:dialog.category?t("分类"):t("标签")})}</p>{dialog.category?<label className="field">{t("选择分类")}<select aria-label={t("选择分类")} value={category} onChange={e=>setCategory(e.target.value)}>{CATEGORIES.map(c=><option key={c} value={c}>{t(c)}</option>)}</select></label>:<label className="field">{t("添加标签")}<input aria-label={t("添加标签")} placeholder={t("如：日常，收藏搭配，待试穿")} value={value} onChange={e=>setValue(e.target.value)}/><span className="help-text">{t("用逗号分隔。已有标签会保留。")}</span></label>}</>:
      dialog.type==='link'?<><p className="modal-description">{t("粘贴 BOOTH 或其他商品网页的公开 HTTPS 链接。")}</p><label className="field">{t("商品网址")}<input aria-label={t("商品网址")} placeholder="https://booth.pm/ja/items/…" value={value} onChange={e=>setValue(e.target.value)}/></label><p className="help-text">{t("保存后读取商品标题、封面和适配信息。")}</p></>:
      <><p className="modal-description">{t("关联「{title}」使用或对应的条目。共选 {count} 项。",{title:displayTitle(dialog.asset),count:related.size})}</p><div className="search-field modal-search"><Icon name="search" size={17}/><input aria-label={t("搜索关联素材")} placeholder={t("搜索素材或工程…")} value={value} onChange={e=>setValue(e.target.value)}/></div><div className="relation-results">{relationLoading&&<p className="help-text">{t("正在查找…")}</p>}{results.map(a=><label className="relation-entry" key={a.id}><input type="checkbox" checked={related.has(a.id)} onChange={()=>setRelated(old=>{const next=new Set(old);next.has(a.id)?next.delete(a.id):next.add(a.id);return next})}/><div className="relation-cover"><Cover asset={a}/></div><div><strong>{displayTitle(a)}</strong><span>{a.group||kindLabel(a.kind)}</span></div></label>)}{!relationLoading&&!results.length&&<p className="help-text">{t("没有找到可关联的条目。")}</p>}</div><p className="help-text">{t("每次显示最多 80 项；可搜索缩小范围。同一素材文件夹内的同名版本会集中展示。")}</p></>}
    </div><div className="modal-footer">{dialog.type==='settings'?<button className="button primary" disabled={busy} onClick={onClose}>{t("完成")}</button>:<><button className="button" disabled={busy} onClick={onClose}>{t("取消")}</button><button className="button primary" disabled={busy||dialog.type==='link'&&!value.trim().toLowerCase().startsWith('https://')||dialog.type==='bulk'&&!dialog.category&&!splitTags(value).length} onClick={save}>{busy?t("正在保存…"):t("保存")}</button></>}</div></div></div>;
}

createRoot(document.getElementById('root')!).render(<App/>);







